// PresignedAvatarUploadURL is the resolver for the presignedAvatarUploadUrl field.
func (r *queryResolver) PresignedAvatarUploadURL(ctx context.Context, contentType string) (*gqlmodel.PresignedUploadURL, error) {
	claims, err := requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	extMap := map[string]string{
		"image/jpeg": ".jpg",
		"image/png":  ".png",
		"image/webp": ".webp",
		"image/gif":  ".gif",
	}
	ext, ok := extMap[contentType]
	if !ok {
		return nil, fmt.Errorf("unsupported content type: %s", contentType)
	}

	const avatarMaxBytes = 5 * 1024 * 1024 // 5 MB

	objectKey := fmt.Sprintf("avatars/%d/%s%s", claims.ID, uuid.New().String(), ext)
	uploadURL, err := r.StorageRepository.PresignedPutURL(ctx, objectKey, contentType, 15*time.Minute, avatarMaxBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to generate upload url")
	}

	return &gqlmodel.PresignedUploadURL{
		UploadURL: uploadURL,
		ObjectKey: objectKey,
	}, nil
}

